    /** 战斗结算：按 npc.Drop 发掉落（统一 drop 入口的第一个消费者）。
     *  请求实测带 `{win, npcID}`（REQ 日志）。去重窗口见 DROP_DEDUP_MS。
     *  应答仍走抓包模板（客户端 `fightBack` 读 e.win / e.npcID），不发 rewardArray —— 掉落直接进账本。 */
    CheckBattleResult: function (p) {
      p = p || {};
      var npc = parseInt(p.npcID, 10) || 0;
      var win = (p.win === true) || (parseInt(p.win, 10) === 1);
      if (npc > 0 && win) {
        var s = ensureLedger(loadSave());
        var now = env.now();
        var lb = s.lastBattle || {};
        var dropId = (typeof BZ_NPCDROP !== 'undefined') ? BZ_NPCDROP[String(npc)] : 0;
        if (!dropId) {
          env.log('打怪掉落 npc=' + npc + ' 无掉落表（npc.Drop 缺失或展开为空）');
        } else if (lb.npc === npc && (now - (parseInt(lb.t, 10) || 0)) < DROP_DEDUP_MS) {
          env.log('打怪掉落 npc=' + npc + ' 跳过（' + (now - lb.t) + 'ms 内重复结算）');
        } else {
          var got = grantFromDrop(s, dropId);
          s.lastBattle = { npc: npc, t: now };
          persist();
          if (got && Object.keys(got).length) env.log('打怪掉落 npc=' + npc + ' drop=' + dropId + ' → ' + JSON.stringify(got));
          else env.log('打怪掉落 npc=' + npc + ' drop=' + dropId + ' 本次没掷中');
        }
      }
      return clone(TPL.checkBattleResult);
    },

